<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class handler extends lib { var $mark = "<!-- THIS CONTENT IS STATIC CACHE THAT CREATED BY QQWORLD COLLECTOR DELUXE -->\n"; var $options; public function init() { } public function get_path($url, $abspath) { $path = dirname($url); $filename = basename($url); if (!preg_match('/\.html?/i', $filename)) { $path .= $path == DIRECTORY_SEPARATOR ? $filename . DIRECTORY_SEPARATOR : DIRECTORY_SEPARATOR . $filename . DIRECTORY_SEPARATOR; $filename = 'index.html'; } $path = urldecode($path); $pathArr = array_values(array_filter(preg_split('/[\\\|\/]/', $path))); if (!is_dir($abspath . $path)) $this->make_dir($pathArr, $abspath); return $abspath . $path . $filename; } public function make_dir($pathArr, $path='', $level = 0) { $path .= DIRECTORY_SEPARATOR . $pathArr[$level]; if (!is_dir($path)) { mkdir($path); } $level++; if ($level < count($pathArr)) $this->make_dir($pathArr, $path, $level); } public function set_cache($path, $args) { $args = apply_filters( 'qqworld-collector-static-cache-fix-url-args', $args); $response = wp_remote_get( home_url($args) ); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { $content = wp_remote_retrieve_body($response); $content = apply_filters( 'qqworld-collector-static-cache-content', $content ); $content = $this->mark . $content; file_put_contents($path, $content); return true; } return false; } } ?>